{"content": """"Regression test for issue #1936.

When a custom ``shell_complete`` function is a generator (uses ``yield``
instead of ``return``), calling ``Parameter.shell_complete`` must not
raise ``TypeError: 'generator' object is not subscriptable``.
"""
import pytest

from click.core import Argument
from click.core import Command
from click.shell_completion import CompletionItem
from click.shell_completion import ShellComplete


def _get_completions(cli, args, incomplete):
    comp = ShellComplete(cli, {}, cli.name, "_CLICK_COMPLETE")
    return comp.get_completions(args, incomplete)


def test_shell_complete_generator() -> None:
    """A custom shell_complete function that is a generator should work."""

    def custom(ctx, param, incomplete):
        for item in ["alpha", "beta", "gamma"]:
            if incomplete in item:
                yield CompletionItem(item)

    cli = Command(
        "cli",
        params=[
            Argument(["x"]),
            Argument(["y"]),
            Argument(["z"], shell_complete=custom),
        ],
    )

    completions = _get_completions(cli, ["a", "b"], "a")
    assert [c.value for c in completions] == ["alpha"]", "path": "tests/test_shell_completion_generator.py"}
